529	/**
530	 * Resolves the request's `Actor` for a given org slug, or throws
531	 * `unauthorized` / `forbidden`. Every Server Action starts here.
532	 *
533	 * The `Actor` is the only thing `can()` and `assertOrgScope()` accept, so
534	 * this module is the seam between "there is an HTTP request with a cookie"
535	 * and the rest of the app, which knows nothing about requests.
536	 */
537	import { getSessionPrincipal } from "@/lib/session";
538	import { assertOrgScope } from "@/lib/tenant";
539	import { findOrgById } from "@/server/repositories/organization-repository";
540	import { resolveActorForOrg } from "@/server/services/session-service";
541	import type { OrgId } from "@/types/common";
542	import type { Actor } from "@/types/member";
543	
544	/** Thrown when there is no usable session; mapped to a 401 by `toAppError`. */
545	export class UnauthorizedError extends Error {
546	  readonly code = "unauthorized" as const;
547	
548	  constructor(message = "Sign in to continue.") {
549	    super(message);
550	    this.name = "UnauthorizedError";
551	  }
552	}
553	
554	/** Thrown when the session is valid but has no membership in the target org. */
555	export class NoMembershipError extends Error {
556	  readonly code = "forbidden" as const;
557	
558	  constructor(readonly orgSlug: string) {
559	    super(`You are not a member of "${orgSlug}".`);
560	    this.name = "NoMembershipError";
561	  }
562	}
563	
564	/** The `Actor` for `orgSlug`, or a throw. Use this in Server Actions. */
565	export async function getActor(orgSlug: string): Promise<Actor> {
566	  const principal = await getSessionPrincipal();
567	  if (principal === null) throw new UnauthorizedError();
568	
569	  const actor = await resolveActorForOrg(principal, orgSlug);
570	  if (actor === null) throw new NoMembershipError(orgSlug);
571	
572	  return actor;
573	}
574	
575	/** Non-throwing variant, for layouts that render a signed-out state. */
576	export async function tryGetActor(orgSlug: string): Promise<Actor | null> {
577	  try {
578	    return await getActor(orgSlug);
579	  } catch (error) {
580	    if (error instanceof UnauthorizedError || error instanceof NoMembershipError) {
581	      return null;
582	    }
583	    throw error;
584	  }
585	}
586	
587	/**
588	 * The `Actor` for an org already identified by id — used by Route Handlers
589	 * that receive an `orgId` in the payload rather than a slug in the path. The
590	 * session's active org must match, which `assertOrgScope()` enforces.
591	 *
592	 * `resolveActorForOrg` keys off the org *slug*, so the id is translated here
593	 * with a single repository lookup rather than by widening that signature —
594	 * the slug is the only handle the session layer knows.
595	 */
596	export async function requireActorFor(orgId: OrgId): Promise<Actor> {
597	  const principal = await getSessionPrincipal();
598	  if (principal === null) throw new UnauthorizedError();
599	  if (principal.activeOrgId === null) throw new NoMembershipError(orgId);
600	
601	  const org = await findOrgById(orgId);
602	  if (org === null) throw new NoMembershipError(orgId);
603	
604	  const actor = await resolveActorForOrg(principal, org.slug);
605	  if (actor === null) throw new NoMembershipError(org.slug);
606	
607	  assertOrgScope(actor, orgId);
608	  return actor;
609	}
