904	function flagAllows(
905	  flag: FeatureFlagKey,
906	  actor: Actor,
907	  flags: FeatureFlagSnapshot,
908	): boolean {
909	  const snapshotted: boolean | undefined = flags[flag];
910	  if (typeof snapshotted === "boolean") return snapshotted;
911	  return isEnabled(flag, {
