921	 * A parent whose every child was filtered away and which has no destination
922	 * of its own is dropped too, so the sidebar never renders an empty group.
923	 */
924	export function visibleNav(
925	  items: readonly NavItem[],
926	  actor: Actor,
927	  flags: FeatureFlagSnapshot,
928	): readonly NavItem[] {
929	  const visible: NavItem[] = [];
930	
931	  for (const item of items) {
932	    if (item.flag !== undefined && !flagAllows(item.flag, actor, flags)) {
933	      continue;
